import subprocess, re
pat=re.compile(rb'\x1b\[48;2;25;25;25m\x1b\[38;2;(\d+);(\d+);(\d+)m(.)\x1b\[49m\x1b\[39m', re.S)
def write(path,tris):
    with open(path,'w') as f:
        f.write("solid T\n")
        for verts in tris:
            f.write("  facet normal 0 0 1\n    outer loop\n")
            for v in verts: f.write(f"      vertex {v[0]} {v[1]} {v[2]}\n")
            f.write("    endloop\n  endfacet\n")
        f.write("endsolid T\n")
def show(label,tris,w=40,h=20):
    write("/tmp/probe/t.stl",tris)
    r=subprocess.run(["./executable","/tmp/probe/t.stl","image","-w",str(w),"-h",str(h)], capture_output=True)
    ms=list(pat.finditer(r.stdout))
    chars=[m.group(4).decode() for m in ms]
    print(label)
    for y in range(h+1):
        row=chars[y*w:(y+1)*w]
        if row: print(y, ''.join(row).replace(chr(10),'N').rstrip())
    print()
