import subprocess, re, math
pat=re.compile(rb'\x1b\[48;2;25;25;25m\x1b\[38;2;(\d+);(\d+);(\d+)m(.)\x1b\[49m\x1b\[39m', re.S)
def ref(path,w,h):
    r=subprocess.run(["./executable",path,"image","-w",str(w),"-h",str(h)], capture_output=True)
    ms=list(pat.finditer(r.stdout)); return [(m.group(4).decode(), (int(m.group(1)),int(m.group(2)),int(m.group(3)))) for m in ms]
def load_stl(path):
    tris=[]; verts=[]
    for line in open(path):
        line=line.strip()
        if line.startswith('vertex'):
            p=line.split(); verts.append(tuple(map(float,p[1:4])))
            if len(verts)==3: tris.append((verts,(255,255,0))); verts=[]
    return tris
def sim_union(tris,w,h,scale_factor=2, agg='any', cxv=None, cyv=None, sample_rule='ge'):
    # virtual dims
    Vw=w*scale_factor; Vh=h*scale_factor
    D=max([0.0]+[c for verts,col in tris for v in verts for c in v])
    # virtual transform analogous to mode A but using virtual w/h
    Fx=min(Vw,2*Vh)/2; Fy=Fx/2
    if cxv is None: cxv=Vw/2+0.5
    if cyv is None: cyv=Vh/2
    # compute virtual coverage grid boolean (depth ignored single layer, use dict for colors approximate as char)
    vbuf={}
    vdepth={}
    for verts,col in tris:
        nv=[tuple(c/D for c in v) for v in verts]
        (x0,y0,z0),(x1,y1,z1),(x2,y2,z2)=nv
        ux,uy,uz=x1-x0,y1-y0,z1-z0; vx,vy,vz=x2-x0,y2-y0,z2-z0
        nz=ux*vy-uy*vx; nx=uy*vz-uz*vy; ny=uz*vx-ux*vz; nl=math.sqrt(nx*nx+ny*ny+nz*nz)
        if nl==0: continue
        if nz/nl<=0: continue
        pts=[(cxv-x*Fx, cyv-y*Fy, z) for x,y,z in nv]
        (ax,ay,az),(bx,by,bz),(cx2,cy2,cz)=pts
        den=(by-cy2)*(ax-cx2)+(cx2-bx)*(ay-cy2)
        if den==0: continue
        for Y in range(Vh):
            for X in range(Vw):
                w0=((by-cy2)*(X-cx2)+(cx2-bx)*(Y-cy2))/den; w1=((cy2-ay)*(X-cx2)+(ax-cx2)*(Y-cy2))/den; w2=1-w0-w1
                if w0>=0 and w1>=0 and w2>=0:
                    z=az*w0+bz*w1+cz*w2; idx=Y*Vw+X
                    if z>vdepth.get(idx,-1e30): vdepth[idx]=z; vbuf[idx]=('@',col)
    buf=[(' ',(0,0,0))]*(w*(h+1))
    for Y in range(h):
        for X in range(w):
            vals=[]
            for dy in range(scale_factor):
                for dx in range(scale_factor):
                    v=vbuf.get((Y*scale_factor+dy)*Vw+(X*scale_factor+dx))
                    if v: vals.append(v)
            if vals:
                # any: if any virtual inside, use first; all: only if all
                if agg=='any' or len(vals)==scale_factor*scale_factor:
                    buf[Y*w+X]=vals[0]
    return buf
def score(sf,agg):
    total=0
    for path,w,h in [("/tmp/probe/centered.stl",40,20),("/tmp/probe/centered.stl",100,50)]:
        tris=load_stl(path); r=ref(path,w,h); s=sim_union(tris,w,h,sf,agg)
