// Geometry types and conversion of loaded model data into triangles.
//
// This module contains the small vector type used by the renderer, the
// triangle type (three raw points plus an RGB colour), and the code which
// resolves Wavefront OBJ material references into per-triangle colours.
// STL triangles receive a fixed yellow colour, mirroring the behaviour of
// the original program, while OBJ triangles use the diffuse (`Kd`) colour
// of their material, scaled to bytes, or a default colour of (1, 1, 1)
// when the OBJ file has no usable material library at all.

use std::fmt;

#[derive(Clone, Copy, Debug, Default)]
pub struct Vec3 {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

impl Vec3 {
    pub fn new(x: f32, y: f32, z: f32) -> Self {
        Vec3 { x, y, z }
    }
    pub fn sub(self, other: Vec3) -> Vec3 {
        Vec3::new(self.x - other.x, self.y - other.y, self.z - other.z)
    }
    pub fn cross(self, other: Vec3) -> Vec3 {
        Vec3::new(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x,
        )
    }
    pub fn length(self) -> f32 {
        (self.x * self.x + self.y * self.y + self.z * self.z).sqrt()
    }
    pub fn divided(self, value: f32) -> Vec3 {
        Vec3::new(self.x / value, self.y / value, self.z / value)
    }
}

impl fmt::Display for Vec3 {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {}, {})", self.x, self.y, self.z)
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Triangle {
    pub points: [Vec3; 3],
    pub colour: (u8, u8, u8),
}

impl Triangle {
    pub fn new(points: [Vec3; 3], colour: (u8, u8, u8)) -> Self {
        Triangle { points, colour }
    }
}

#[derive(Clone, Debug)]
pub struct Material {
    pub name: String,
    pub diffuse: [f32; 3],
}

#[derive(Clone, Debug)]
pub struct ObjFace {
    pub points: Vec<Vec3>,
    pub material: Option<String>,
}

pub enum LoadedFile {
    Obj {
        faces: Vec<ObjFace>,
        materials: Vec<Material>,
    },
    Stl {
        triangles: Vec<[Vec3; 3]>,
    },
}

fn diffuse_to_colour(diffuse: [f32; 3]) -> (u8, u8, u8) {
    (
        (diffuse[0] * 255.0) as u8,
        (diffuse[1] * 255.0) as u8,
        (diffuse[2] * 255.0) as u8,
    )
}

fn face_colour(material: &Option<String>, materials: &Vec<Material>) -> (u8, u8, u8) {
    if materials.is_empty() {
        return (1, 1, 1);
    }
    let found = materials.iter().find(|candidate| material.as_ref() == Some(&candidate.name));










    let resolved = found.unwrap();
    diffuse_to_colour(resolved.diffuse)
}

pub fn build_triangles(files: Vec<LoadedFile>) -> Vec<Triangle> {
    let mut triangles = Vec::new();
    for file in files {
        match file {
            LoadedFile::Obj { faces, materials } => {
                for face in &faces {
                    if face.points.len() < 3 {
                        continue;
                    }
                    let colour = face_colour(&face.material, &materials);
                    for index in 1..face.points.len() - 1 {
                        triangles.push(Triangle::new(
                            [face.points[0], face.points[index], face.points[index + 1]],
                            colour,
                        ));
                    }
                }
            }
            LoadedFile::Stl { triangles: facets } => {
                for points in facets {
                    triangles.push(Triangle::new(points, (255, 255, 0)));
                }
            }
        }
    }
    triangles
}
