//! A small software rasterizer which renders coloured ASCII characters.
//!
//! Triangles are rendered at half horizontal resolution: each logical
//! raster pixel covers two adjacent characters in the resulting output.
//! This gives the characters, which are roughly twice as tall as they are
//! wide, an approximately square appearance.  A pixel in the output is
//! represented with an ANSI true-colour escape sequence (see the Display
//! impl below), or with a bare character when colour is disabled.
//!
//! Rendering uses a scan-line triangle filler: for each scan line in a
//! triangle's Y range, the intersections with the triangle edges are
//! found, and the span between them is filled.  Depth is interpolated
//! along each span, and a per-pixel depth buffer keeps the closest
//! (largest Z) surface.

use crate::geometry::{Triangle, Vec3};
use std::f32::consts::PI;

#[derive(Clone, Copy, Debug)]
pub struct Pixel {
    pub character: char,
    pub colour: (u8, u8, u8),
}

impl Pixel {
    pub fn background() -> Pixel {
        Pixel {
            character: ' ',
            colour: (0, 0, 0),
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Rotation {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

fn rotate(point: Vec3, rotation: Rotation) -> Vec3 {
    let (sin, cos) = rotation.x.sin_cos();
    let point = Vec3::new(
        point.x,
        point.y * cos - point.z * sin,
        point.y * sin + point.z * cos,
    );
    let (sin, cos) = rotation.y.sin_cos();
    let point = Vec3::new(
        point.x * cos + point.z * sin,
        point.y,
        -point.x * sin + point.z * cos,
    );
    let (sin, cos) = rotation.z.sin_cos();
    Vec3::new(
        point.x * cos + point.y * sin,
        -point.x * sin + point.y * cos,
        point.z,
    )
}

fn shade_character(intensity: f32) -> char {
    if intensity >= 0.9 {
        '@'
    } else if intensity >= 0.8 {
        '%'
    } else if intensity >= 0.7 {
        '#'
    } else if intensity >= 0.6 {
        '*'
    } else if intensity >= 0.5 {
        '+'
    } else if intensity >= 0.4 {
        '='
    } else if intensity >= 0.3 {
        '-'
    } else if intensity >= 0.2 {
        ':'
    } else {
        '.'
    }
}

pub struct Rasterizer {
    pub width: usize,
    pub height: usize,
    pub pixels: Vec<Pixel>,
    depth: Vec<f32>,
    ranges: Vec<(i32, i32)>,
}

impl Rasterizer {
    pub fn new(width: usize, height: usize) -> Rasterizer {
        Rasterizer {
            width,
            height,
            pixels: vec![Pixel::background(); (width + 1) * height],
            depth: vec![f32::NEG_INFINITY; (width + 1) * height],
            ranges: Vec::new(),
        }
    }

    pub fn render(&mut self, triangles: &Vec<Triangle>, rotation: Rotation) {
        for p in self.pixels.iter_mut() {
            *p = Pixel::background();
        }
        for d in self.depth.iter_mut() {
            *d = f32::NEG_INFINITY;
        }
        self.ranges.clear();
        let mut largest = 0.0f32;
        for triangle in triangles {
            for point in triangle.points {
                if point.x > largest {
                    largest = point.x;
                }
                if point.y > largest {
                    largest = point.y;
                }
                if point.z > largest {
                    largest = point.z;
                }
            }
        }
        for triangle in triangles {
            self.draw_triangle(triangle, largest, rotation);
        }
    }

    fn draw_triangle(&mut self, triangle: &Triangle, largest: f32, rotation: Rotation) {
        let mut points = [Vec3::default(); 3];
        for i in 0..3 {
            points[i] = rotate(triangle.points[i].divided(largest), rotation);
        }
        let a = points[0];
        let b = points[1];
        let c = points[2];
        let first = b.sub(a);
        let second = c.sub(a);
        let crossed = first.cross(second);
        let len = crossed.length();
        let normal = crossed.divided(len);
        let scale = (self.width as f32 / 2.0).min(self.height as f32) / 2.0;
        let centre_x = self.width as f32 / 4.0;
        let centre_y = self.height as f32 / 2.0;
        let mut screen = [Vec3::default(); 3];
        for i in 0..3 {
            screen[i] = Vec3::new(
                centre_x - points[i].x * scale,
                centre_y - points[i].y * scale,
                points[i].z,
            );
        }
        let min_y = screen[0].y.min(screen[1].y).min(screen[2].y);
        let max_y = screen[0].y.max(screen[1].y).max(screen[2].y);
        self.ranges
            .push((min_y.ceil() as i32, max_y.ceil() as i32));
        let intensity = normal.z;
        if intensity <= 0.0 {
            return;
        }
        let character = shade_character(intensity);
        let pixel = Pixel {
            character,
            colour: triangle.colour,
        };
