                } else {
                    zl + (zr - zl) * ((x as f32 - xl) / (xr - xl))
                };
                self.put_logical(x, y, z, pixel);
                x += 1;
            }
        }
    }

    fn put_logical(&mut self, x: i32, y: i32, z: f32, pixel: Pixel) {
        let mut out_x = x * 2;
        for _ in 0..2 {
            let index = y as i64 * self.width as i64 + out_x as i64;
            if index >= 0 && (index as usize) < self.pixels.len() {
                let idx = index as usize;
                if z > self.depth[idx] {
                    self.depth[idx] = z;
                    self.pixels[idx] = pixel;
                }
            }
            out_x += 1;
        }
    }

