//! single combined scene.  If several input values are supplied as
//! separate arguments, only the first one is used, mirroring the
//! original's use of Clap's single-value accessor.

use crate::geometry::{LoadedFile, Material, ObjFace, Vec3};
use std::error::Error;
use std::fmt;
use std::fs::File;
use std::io::Read;
use std::path::Path;

// =======================================================================
// Errors returned from main, printed as `Error: <debug>`.
// =======================================================================

#[derive(Debug)]
pub enum MainError {
    IoError(std::io::Error),
}

impl fmt::Display for MainError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            MainError::IoError(error) => write!(f, "{}", error),
        }
    }
}

impl Error for MainError {}

// =======================================================================
// Command-line parsing
// =======================================================================

pub struct ImageOptions {
    pub colourless_flag_present: bool,
    pub width: Option<String>,
    pub height: Option<String>,
    pub webify: Option<String>,
    pub x: Option<String>,
    pub y: Option<String>,
    pub z: Option<String>,
    pub started_without_input: bool,
}

pub struct Options {
    pub inputs: Vec<String>,
    pub no_colour: bool,
    pub x: Option<String>,
    pub y: Option<String>,
    pub z: Option<String>,
    pub image: Option<ImageOptions>,
}

fn bin_name() -> String {
    let mut args = std::env::args();
    if let Some(first) = args.next() {
        let name = Path::new(&first)
            .file_name()
            .map(|value| value.to_string_lossy().into_owned())
            .unwrap_or(first.clone());
        if name.is_empty() {
            "sloth".to_string()
        } else {
            name
        }
    } else {
        "sloth".to_string()
    }
}

fn main_help(bin: &str) -> String {
    format!(
        "Sloth 0.1\nMitchell Hynes. <mshynes@mun.ca>\nA toy for rendering 3D objects in the command line\n\nUSAGE:\n    {bin} [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -x, --yaw <x>      Sets the object's static X rotation (in radians)\n    -y, --pitch <y>    Sets the object's static Y rotation (in radians)\n    -z, --roll <z>     Sets the object's static Z rotation (in radians)\n\nARGS:\n    <input filename(s)>...    Sets the input file to render\n\nSUBCOMMANDS:\n    help     Prints this message or the help of the given subcommand(s)\n    image    Generates a colorless terminal output as lines of text\n",
        bin = bin
    )
}

fn image_help(bin: &str, with_input: bool) -> String {
    let usage = if with_input {
        format!("{} <input filename(s)>... image", bin)
    } else {
