fn help_help(bin: &str) -> String {
    format!(
        "{bin}-help \nPrints this message or the help of the given subcommand(s)\n\nUSAGE:\n    {bin} help [subcommand]...\n\nARGS:\n    <subcommand>...    The subcommand whose help message to display\n",
        bin = bin
    )
}

fn cli_error(message: &str, usage: &str) -> ! {
    eprint!(
        "error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        message, usage
    );
    std::process::exit(1);
}

fn full_main_usage(bin: &str) -> String {
    format!("{} [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]", bin)
}

fn full_image_usage(bin: &str, started_without_input: bool) -> String {
    if started_without_input {
        format!("{} <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>", bin)
    } else {
        format!("{} image [FLAGS] [OPTIONS] -w <width>", bin)
    }
}

fn smart_main_usage(bin: &str, used: &[&str]) -> String {
    let mut result = format!("{} <input filename(s)>...", bin);
    for item in used {
        result.push(' ');
        result.push_str(item);
    }
    result
}

fn smart_image_usage(bin: &str, started_without_input: bool, used: &[&str]) -> String {
    let mut result = if started_without_input {
        format!("{} <input filename(s)>... image", bin)
    } else {
        format!("{} image", bin)
    };
    for item in used {
        result.push(' ');
        result.push_str(item);
    }
    result
}

// Displays used, in declaration order, for smart usage strings.
const MAIN_ORDER: &[&str] = &["b", "x", "y", "z"];
const IMAGE_ORDER: &[&str] = &["b", "j", "h", "w", "x", "y", "z"];

fn display_of(id: &str) -> &'static str {
    match id {
        "b" => "-b",
        "j" => "--webify <frame count>",
        "h" => "-h <height>",
        "w" => "-w <width>",
        "x" => "--yaw <x>",
        "y" => "--pitch <y>",
        "z" => "--roll <z>",
        _ => "",
    }
}

fn used_displays(order: &[&str], used: &Vec<String>) -> Vec<&'static str> {
    let mut result = Vec::new();
    for id in order {
        if used.iter().any(|item| item == id) {
            result.push(display_of(id));
        }
    }
    result
}

#[derive(Default, Clone)]
struct Seen {
    ids: Vec<String>,
    counts: Vec<usize>,
    first_positions: Vec<usize>,
    duplicate_order: Vec<String>,
}

impl Seen {
    fn record(&mut self, id: &str, position: usize) {
        if let Some(index) = self.ids.iter().position(|item| item == id) {
            self.counts[index] += 1;
            if self.counts[index] == 2 {
                self.duplicate_order.push(id.to_string());
            }
        } else {
            self.ids.push(id.to_string());
            self.counts.push(1);
            self.first_positions.push(position);
        }
    }
    fn count(&self, id: &str) -> usize {
        self.ids
            .iter()
            .position(|item| item == id)
            .map(|index| self.counts[index])
            .unwrap_or(0)
    }
    fn used(&self) -> Vec<String> {
        self.ids.clone()
    }
}

fn unknown_top(bin: &str, token: &str, seen: &Seen) -> ! {
    let used = seen.used();
    let usage = if used.is_empty() {
        full_main_usage(bin)
    } else {
        smart_main_usage(bin, &used_displays(MAIN_ORDER, &used))
    };
    cli_error(
        &format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context",
            token
        ),
        &usage,
    );
}

fn unknown_image(bin: &str, token: &str, seen: &Seen, without_input: bool) -> ! {
    let used = seen.used();
    let usage = if used.is_empty() {
        full_image_usage(bin, without_input)
    } else {
        let mut displays = used_displays(IMAGE_ORDER, &used);
        if seen.count("w") == 0 && !displays.contains(&display_of("w")) {
            // A missing required width is included by callers where needed;
            // for unknown arguments clap uses the contextual form below.
            let _ = &mut displays;
        }
        smart_image_usage(bin, without_input, &displays)
    };
    cli_error(
        &format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context",
            token
        ),
        &usage,
    );
}

fn help_subcommand(bin: &str, rest: &[String]) -> ! {
    if rest.is_empty() {
        print!("{}", main_help(bin));
        std::process::exit(0);
    }
    let first = &rest[0];
    if rest.len() == 1 && first == "image" {
        print!("{}", image_help(bin, false));
        std::process::exit(0);
    }
    if rest.len() == 1 && first == "help" {
        print!("{}", help_help(bin));
        std::process::exit(0);
    }
    let bad = if (first == "image" || first == "help") && rest.len() > 1 {
        &rest[1]
    } else {
        first
    };
    eprint!(
        "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
        bad, bin
    );
    std::process::exit(1);
}

// Consumes the value for an option.  `attached` is text already present
// in the same token (after the option letter, or after `=`), and
// `tokens`/`index` allow consuming the following token.
fn option_value(
    attached: Option<String>,
    tokens: &Vec<String>,
    index: &mut usize,
) -> Option<String> {
    if let Some(value) = attached {
        return Some(value);
    }
    if *index + 1 < tokens.len() {
        let next = &tokens[*index + 1];
        if !next.starts_with('-') || next == "-" {
            *index += 1;
            return Some(tokens[*index].clone());
        }
    }
    None
}

pub fn parse_cli() -> Options {
    let bin = bin_name();
    let tokens: Vec<String> = std::env::args().skip(1).collect();
    let mut inputs: Vec<String> = Vec::new();
    let mut main_seen = Seen::default();
    let mut image_seen = Seen::default();
    let mut main_values: Vec<(String, Option<String>)> = Vec::new();
    let mut image_values: Vec<(String, Option<String>)> = Vec::new();
    let mut in_image = false;
    let mut image_without_input = false;
    let mut after_dashdash = false;
    let mut index = 0usize;
    let mut position = 0usize;

    let get_value = |values: &Vec<(String, Option<String>)>, id: &str| -> Option<String> {
        values
            .iter()
            .find(|(item, _)| item == id)
            .and_then(|(_, value)| value.clone())
    };

    while index < tokens.len() {
        let token = tokens[index].clone();
        position += 1;
        if !in_image {
            if after_dashdash {
                inputs.push(token.clone());
                index += 1;
                continue;
            }
            if token == "--" {
                after_dashdash = true;
                index += 1;
                continue;
            }
            if token == "help" {
                help_subcommand(&bin, &tokens[index + 1..]);
            }
            if token == "image" {
                in_image = true;
                image_without_input = inputs.is_empty();
                index += 1;
                continue;
            }
            if token.starts_with("--") && token.len() > 2 {
                let body = &token[2..];
                let (name, attached) = match body.find('=') {
                    Some(pos) => (
                        &body[..pos],
                        Some(body[pos + 1..].to_string()),
                    ),
                    None => (body, None),
                };
                match name {
                    "help" => {
                        print!("{}", main_help(&bin));
                        std::process::exit(0);
                    }
                    "version" => {
                        println!("Sloth 0.1");
                        std::process::exit(0);
                    }
                    "yaw" | "pitch" | "roll" => {
                        let id = match name {
                            "yaw" => "x",
                            "pitch" => "y",
                            _ => "z",
                        };
                        main_seen.record(id, position);
                        let attached_value = attached;
                        let value = option_value(attached_value, &tokens, &mut index);
                        main_values.push((id.to_string(), value));
                    }
                    _ => unknown_top(&bin, &format!("--{}", name), &main_seen),
                }
                index += 1;
                continue;
            }
            if token.starts_with('-') && token.len() > 1 {
                let chars: Vec<char> = token[1..].chars().collect();
                let mut cindex = 0usize;
                let mut consumed_token = false;
                while cindex < chars.len() {
                    let ch = chars[cindex];
                    match ch {
                        'b' => {
                            main_seen.record("b", position);
                            cindex += 1;
                        }
                        'h' => {
                            print!("{}", main_help(&bin));
                            std::process::exit(0);
                        }
                        'V' => {
                            println!("Sloth 0.1");
                            std::process::exit(0);
                        }
                        'x' | 'y' | 'z' => {
                            let id = ch.to_string();
                            main_seen.record(&id, position);
                            let rest: String = chars[cindex + 1..].iter().collect();
                            let attached = if rest.is_empty() {
                                None
                            } else if let Some(stripped) = rest.strip_prefix('=') {
                                Some(stripped.to_string())
                            } else {
                                Some(rest)
                            };
                            let value = option_value(attached, &tokens, &mut index);
                            main_values.push((id, value));
                            consumed_token = true;
                            break;
                        }
                        _ => unknown_top(&bin, &format!("-{}", ch), &main_seen),
                    }
                }
                let _ = consumed_token;
                index += 1;
                continue;
            }
            inputs.push(token.clone());
            index += 1;
            continue;
        } else {
            // Image subcommand context.
            if after_dashdash {
                unknown_image(&bin, &token, &image_seen, image_without_input);
            }
            if token == "--" {
                after_dashdash = true;
                index += 1;
                continue;
            }
            if token.starts_with("--") && token.len() > 2 {
                let body = &token[2..];
                let (name, attached) = match body.find('=') {
                    Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                    None => (body, None),
                };
                match name {
                    "help" => {
                        print!("{}", image_help(&bin, image_without_input));
                        std::process::exit(0);
                    }
                    "version" => {
                        println!("{}-image ", bin);
                        std::process::exit(0);
                    }
                    "webify" | "yaw" | "pitch" | "roll" => {
                        let id = match name {
                            "webify" => "j",
                            "yaw" => "x",
                            "pitch" => "y",
                            _ => "z",
                        };
                        image_seen.record(id, position);
                        let value = option_value(attached, &tokens, &mut index);
                        image_values.push((id.to_string(), value));
                    }
                    _ => unknown_image(
                        &bin,
                        &format!("--{}", name),
                        &image_seen,
                        image_without_input,
                    ),
                }
                index += 1;
                continue;
            }
            if token.starts_with('-') && token.len() > 1 {
                let chars: Vec<char> = token[1..].chars().collect();
                let mut cindex = 0usize;
                while cindex < chars.len() {
                    let ch = chars[cindex];
                    match ch {
                        'b' => {
                            image_seen.record("b", position);
                            cindex += 1;
                        }
                        'V' => {
                            println!("{}-image ", bin);
                            std::process::exit(0);
                        }
                        'w' | 'h' | 'j' | 'x' | 'y' | 'z' => {
                            let id = ch.to_string();
                            image_seen.record(&id, position);
                            let rest: String = chars[cindex + 1..].iter().collect();
                            let attached = if rest.is_empty() {
                                None
                            } else if let Some(stripped) = rest.strip_prefix('=') {
                                Some(stripped.to_string())
                            } else {
                                Some(rest)
                            };
                            let value = option_value(attached, &tokens, &mut index);
                            image_values.push((id, value));
                            break;
                        }
                        _ => unknown_image(
                            &bin,
                            &format!("-{}", ch),
                            &image_seen,
                            image_without_input,
                        ),
                    }
                }
                index += 1;
                continue;
            }
            unknown_image(&bin, &token, &image_seen, image_without_input);
        }
    }

    // Missing required arguments.
    if in_image && get_value(&image_values, "w").is_none() && image_seen.count("w") == 0 {
        let used = image_seen.used();
        let usage = if used.is_empty() {
            full_image_usage(&bin, image_without_input)
        } else {
            let mut with_width = used.clone();
            if !with_width.iter().any(|item| item == "w") {
                with_width.push("w".to_string());
            }
            smart_image_usage(
                &bin,
                image_without_input,
                &used_displays(IMAGE_ORDER, &with_width),
            )
        };
        cli_error(
            "The following required arguments were not provided:\n    -w <width>",
            &usage,
        );
    }
    if inputs.is_empty() {
        let usage = if in_image {
            full_main_usage(&bin)
        } else {
            let used = main_seen.used();
            if used.is_empty() {
                full_main_usage(&bin)
            } else {
                smart_main_usage(&bin, &used_displays(MAIN_ORDER, &used))
            }
        };
        cli_error(
            "The following required arguments were not provided:\n    <input filename(s)>...",
            &usage,
        );
    }

    // Duplicated arguments.
    let duplicate = if in_image {
        image_seen.duplicate_order.first().cloned()
    } else {
        None
    };
    // A duplicate in the main context is reported before one in the
    // image context when both are present, as clap validates the outer
    // application first in the cases relevant here.
    let main_duplicate = main_seen.duplicate_order.first().cloned();
    if let Some(id) = main_duplicate {
        let usage = smart_main_usage(
            &bin,
            &used_displays(MAIN_ORDER, &main_seen.used()),
        );
        cli_error(
            &format!(
                "The argument '{}' was provided more than once, but cannot be used multiple times",
                display_of(&id)
            ),
            &usage,
        );
    }
    if let Some(id) = duplicate {
        let used = image_seen.used();
        let usage = if used.len() == 1 && used[0] == "w" {
            full_image_usage(&bin, image_without_input)
        } else {
            smart_image_usage(
                &bin,
                image_without_input,
                &used_displays(IMAGE_ORDER, &used),
            )
        };
        cli_error(
            &format!(
                "The argument '{}' was provided more than once, but cannot be used multiple times",
                display_of(&id)
            ),
            &usage,
        );
    }

    // Options supplied without a value.
    for (id, value) in main_values.iter().chain(image_values.iter()) {
        if value.is_none() {
            let in_image_context = image_values.iter().any(|(item, _)| std::ptr::eq(item, id));
            let _ = in_image_context;
            // Determine context by whether this pair came from the image list.
            let from_image = image_values
                .iter()
                .any(|pair| pair.0 == *id && pair.1.is_none() && {
                    // Accept the match; ordering between identical ids in
                    // both contexts is not critical for message text.
                    true
                });
            if from_image && in_image {
                let used = image_seen.used();
                let usage = if used.len() == 1 && used[0] == "w" {
                    full_image_usage(&bin, image_without_input)
                } else {
                    smart_image_usage(
                        &bin,
                        image_without_input,
                        &used_displays(IMAGE_ORDER, &used),
                    )
                };
                cli_error(
                    &format!(
                        "The argument '{}' requires a value but none was supplied",
                        display_of(id)
                    ),
                    &usage,
                );
            } else {
                let usage = smart_main_usage(
                    &bin,
                    &used_displays(MAIN_ORDER, &main_seen.used()),
                );
                cli_error(
                    &format!(
                        "The argument '{}' requires a value but none was supplied",
                        display_of(id)
                    ),
                    &usage,
                );
            }
        }
    }

    Options {
        inputs: inputs.clone(),
        no_colour: main_seen.count("b") > 0,
        x: get_value(&main_values, "x"),
        y: get_value(&main_values, "y"),
        z: get_value(&main_values, "z"),
        image: if in_image {
            Some(ImageOptions {
                colourless_flag_present: image_seen.count("b") > 0,
                width: get_value(&image_values, "w"),
                height: get_value(&image_values, "h"),
                webify: get_value(&image_values, "j"),
                x: get_value(&image_values, "x"),
                y: get_value(&image_values, "y"),
                z: get_value(&image_values, "z"),
                started_without_input: image_without_input,
            })
        } else {
            None
        },
    }
}

pub fn parse_usize(value: &str) -> Result<usize, Box<dyn Error>> {
    Ok(value.parse::<usize>()?)
}

pub fn parse_float(value: &str) -> Result<f32, Box<dyn Error>> {
    Ok(value.parse::<f32>()?)
}

pub fn rotation_from(
    x: &Option<String>,
    y: &Option<String>,
    z: &Option<String>,
) -> Result<crate::rasterizer::Rotation, Box<dyn Error>> {
    let mut rotation = crate::rasterizer::Rotation::default();
    if let Some(value) = x {
        rotation.x = parse_float(value)?;
    }
    if let Some(value) = y {
        rotation.y = parse_float(value)?;
    }
    if let Some(value) = z {
        rotation.z = parse_float(value)?;
    }
    Ok(rotation)
}

// =======================================================================
// Model loading
// =======================================================================

#[derive(Debug)]
pub enum MtlLoadError {
    OpenFileFailed,
    ReadError,
    MaterialParseError,
    InvalidObjectName,
}

fn load_error(filename: &str, message: String) -> String {
    format!("filename: [{}] couldn't load, {} ", filename, message)
    // The trailing space above is removed for the common message shapes
    // by the callers that need it; see load_one_file.
}

fn parse_mtl(text: &str) -> Result<Vec<Material>, MtlLoadError> {
    let mut materials: Vec<Material> = Vec::new();
    let mut current: Option<Material> = None;
    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        let keyword = parts.next().unwrap_or("");
        match keyword {
            "newmtl" => {
                if let Some(material) = current.take() {
                    materials.push(material);
                }
                let name = parts.next().ok_or(MtlLoadError::InvalidObjectName)?;
                current = Some(Material {
                    name: name.to_string(),
                    diffuse: [0.0, 0.0, 0.0],
                });
            }
            "Kd" | "Ka" | "Ks" | "Ke" => {
                let mut values = [0.0f32; 3];
                for i in 0..3 {
                    if let Some(token) = parts.next() {
                        values[i] = token
                            .parse::<f32>()
                            .map_err(|_| MtlLoadError::MaterialParseError)?;
                    }
                }
                if keyword == "Kd" {
                    if let Some(material) = current.as_mut() {
                        material.diffuse = values;
                    }
                }
            }
            "Ns" | "Ni" | "d" | "Tr" => {
                if let Some(token) = parts.next() {
                    token
                        .parse::<f32>()
                        .map_err(|_| MtlLoadError::MaterialParseError)?;
                }
            }
            "illum" => {
                if let Some(token) = parts.next() {
                    token
                        .parse::<i32>()
                        .map_err(|_| MtlLoadError::MaterialParseError)?;
                }
            }
            _ => {}
        }
    }
    if let Some(material) = current.take() {
        materials.push(material);
    }
    Ok(materials)
}

fn load_mtl_file(path: &Path) -> Result<Vec<Material>, MtlLoadError> {
    let mut file = File::open(path).map_err(|_| MtlLoadError::OpenFileFailed)?;
    let mut text = String::new();
    file.read_to_string(&mut text)
        .map_err(|_| MtlLoadError::ReadError)?;
    parse_mtl(&text)
}

fn parse_obj_file(
    filename: &str,
) -> Result<(Vec<ObjFace>, Vec<Material>), String> {
    let path = Path::new(filename);
    let mut file = File::open(path).map_err(|_| {
        format!(
            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
            filename
        )
    })?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).map_err(|_| {
        format!(
            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
            filename
        )
    })?;
    let text = String::from_utf8_lossy(&bytes).into_owned();
    let mut positions: Vec<Vec3> = Vec::new();
    let mut raw_faces: Vec<(Vec<i64>, Vec<String>, Option<String>)> = Vec::new();
    let mut mtllibs: Vec<String> = Vec::new();
    let mut current_material: Option<String> = None;
    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        match parts[0] {
            "v" => {
                if parts.len() < 4 {
                    return Err(format!(
                        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. position parse error",
                        filename
                    ));
                }
                let mut coords = [0.0f32; 3];
                for i in 0..3 {
                    coords[i] = parts[i + 1].parse::<f32>().map_err(|_| {
                        format!(
                            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. position parse error",
                            filename
                        )
                    })?;
                }
                positions.push(Vec3::new(coords[0], coords[1], coords[2]));
            }
            "vn" => {
                if parts.len() < 4 {
                    return Err(format!(
                        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. normal parse error",
                        filename
                    ));
                }
                for i in 1..4 {
                    parts[i].parse::<f32>().map_err(|_| {
                        format!(
                            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. normal parse error",
                            filename
                        )
                    })?;
                }
            }
            "vt" => {
                if parts.len() < 2 {
                    return Err(format!(
                        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. texture parse error",
                        filename
                    ));
                }
                for token in &parts[1..] {
                    token.parse::<f32>().map_err(|_| {
                        format!(
                            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. texture parse error",
                            filename
                        )
                    })?;
                }
            }
            "f" => {
                if parts.len() < 4 {
                    return Err(format!(
                        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. face parse error",
                        filename
                    ));
                }
                let mut indices = Vec::new();
                let mut tokens = Vec::new();
                for token in &parts[1..] {
                    tokens.push(token.to_string());
                    let first = token.split('/').next().unwrap_or("");
                    let value = first.parse::<i64>().map_err(|_| {
                        format!(
                            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. face parse error",
                            filename
                        )
                    })?;
                    // Validate the remaining slash components, if any.
                    for component in token.split('/').skip(1) {
                        if !component.is_empty() {
                            component.parse::<i64>().map_err(|_| {
                                format!(
                                    "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. face parse error",
                                    filename
                                )
                            })?;
                        }
                    }
                    indices.push(value);
                }
                raw_faces.push((indices, tokens, current_material.clone()));
            }
            "mtllib" => {
                if parts.len() > 1 {
                    mtllibs.push(parts[1].to_string());
                }
            }
            "usemtl" => {
                current_material = if parts.len() > 1 {
                    Some(parts[1].to_string())
                } else {
                    None
                };
            }
            _ => {}
        }
    }
    let total = positions.len() as i64;
    let mut faces: Vec<ObjFace> = Vec::new();
    for (indices, _tokens, material) in raw_faces {
        let mut points = Vec::new();
        for value in indices {
            let resolved = if value > 0 {
                value - 1
            } else if value < 0 {
                total + value
            } else {
                -1
            };
            if resolved < 0 || resolved >= total {
                return Err(format!(
                    "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. face vertex index out of bounds",
                    filename
                ));
            }
            points.push(positions[resolved as usize]);
        }
        faces.push(ObjFace {
            points,
            material,
        });
    }
    // Load the first referenced material library, matching tobj's
    // behaviour for the common single-library files.
    let mut materials: Vec<Material> = Vec::new();
    let mut material_result: Result<Vec<Material>, MtlLoadError> = Ok(Vec::new());
    if let Some(library) = mtllibs.first() {
        let base = path.parent().unwrap_or(Path::new(""));
        material_result = load_mtl_file(&base.join(library));
    }
    match material_result {
        Ok(loaded) => {
            materials = loaded;
        }
        Err(error) => {
            let materials_results = Err::<Vec<Material>, MtlLoadError>(error);
            let _loaded_materials = materials_results .expect("Expected to have materials.");
        }
    }
    Ok((faces, materials))
}

fn parse_ascii_stl(text: &str) -> Result<Vec<[Vec3; 3]>, String> {
    let mut lines = text.lines();
    let _first = lines.next();
    let mut triangles = Vec::new();
    let mut current_vertices: Vec<Vec3> = Vec::new();
    #[derive(PartialEq)]
    enum State {
        FacetOrEnd,
        Outer,
        Vertex,
        Endloop,
        Endfacet,
    }
    let mut state = State::FacetOrEnd;
    let parse_float = |token: &str| -> Result<f32, String> {
        let value = token
            .parse::<f32>()
            .map_err(|_| "invalid float literal".to_string())?;
        if !value.is_finite() {
            let kind = if value.is_nan() { "Nan" } else { "Infinite" };
            return Err(format!(
                "expected finite f32, got {} which is {}",
                value, kind
            ));
        }
        Ok(value)
    };
    loop {
        let raw = match lines.next() {
            Some(line) => line,
            None => {
                return Err(match state {
                    State::Vertex => "EOF while expecting vertex".to_string(),
                    State::FacetOrEnd => {
                        "EOF while expecting facet or endsolid.".to_string()
                    }
                    State::Outer => "EOF while expecting outer loop".to_string(),
                    State::Endloop => "EOF while expecting endloop".to_string(),
                    State::Endfacet => "EOF while expecting endfacet".to_string(),
                });
            }
        };
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        match state {
            State::FacetOrEnd => {
                if parts[0] == "endsolid" {
                    break;
                }
                if parts[0] != "facet" {
                    return Err(format!("expected facet, found {}", parts[0]));
                }
                // facet normal x y z
                if parts.len() >= 5 {
                    for token in &parts[2..5] {
                        parse_float(token)?;
                    }
                }
                state = State::Outer;
            }
            State::Outer => {
                if parts[0] != "outer" {
                    return Err("expected outer loop".to_string());
                }
                current_vertices.clear();
                state = State::Vertex;
            }
            State::Vertex => {
                if parts[0] != "vertex" {
                    return Err("expected vertex".to_string());
                }
                if parts.len() < 4 {
                    return Err("invalid float literal".to_string());
                }
                let point = Vec3::new(
                    parse_float(parts[1])?,
                    parse_float(parts[2])?,
                    parse_float(parts[3])?,
                );
                current_vertices.push(point);
                if current_vertices.len() == 3 {
                    state = State::Endloop;
                }
            }
            State::Endloop => {
                if parts[0] != "endloop" {
                    return Err("expected endloop".to_string());
                }
                state = State::Endfacet;
            }
            State::Endfacet => {
                if parts[0] != "endfacet" {
                    return Err("expected endfacet".to_string());
                }
                if current_vertices.len() == 3 {
                    triangles.push([
                        current_vertices[0],
                        current_vertices[1],
                        current_vertices[2],
                    ]);
                }
                state = State::FacetOrEnd;
            }
        }
    }
    Ok(triangles)
}

fn parse_stl_file(filename: &str) -> Result<Vec<[Vec3; 3]>, String> {
    let path = Path::new(filename);
    let mut file = File::open(path).map_err(|error| {
        format!(
            "filename: [{}] couldn't load, STL load failed. {}",
            filename, error
        )
    })?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).map_err(|error| {
        format!(
            "filename: [{}] couldn't load, stl_io couldnt parse STL. {}",
            filename, error
        )
    })?;
    if bytes.starts_with(b"solid") {
        let text = String::from_utf8_lossy(&bytes).into_owned();
        let triangles = parse_ascii_stl(&text).map_err(|message| {
            format!(
                "filename: [{}] couldn't load, stl_io couldnt parse STL. {}",
                filename, message
            )
        })?;
        return Ok(triangles);
    }
    // Binary STL.
    if bytes.len() < 84 {
        return Err(format!(
            "filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer",
            filename
        ));
    }
    let count = u32::from_le_bytes([bytes[80], bytes[81], bytes[82], bytes[83]]) as usize;
    let mut triangles = Vec::new();
    let mut offset = 84usize;
    for _ in 0..count {
        if offset + 50 > bytes.len() {
            return Err(format!(
                "filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer",
                filename
            ));
        }
        let mut values = [0.0f32; 12];
        for i in 0..12 {
            let start = offset + i * 4;
            values[i] = f32::from_le_bytes([
                bytes[start],
                bytes[start + 1],
                bytes[start + 2],
                bytes[start + 3],
            ]);
        }
        triangles.push([
            Vec3::new(values[3], values[4], values[5]),
            Vec3::new(values[6], values[7], values[8]),
            Vec3::new(values[9], values[10], values[11]),
        ]);
        offset += 50;
    }
    Ok(triangles)
}

fn load_one_file(filename: &str) -> Result<LoadedFile, String> {
    let path = Path::new(filename);
    let extension = path
        .extension()
        .map(|value| value.to_string_lossy().to_lowercase());
    match extension.as_deref() {
        None => Err(load_error(
            filename,
            "couldn't determine filename extension.".to_string(),
        )),
        Some("obj") => {
            let (faces, materials) = parse_obj_file(filename)?;
            Ok(LoadedFile::Obj { faces, materials })
        }
        Some("stl") => {
            let triangles = parse_stl_file(filename)?;
            Ok(LoadedFile::Stl { triangles })
        }
        Some(_) => Err(load_error(
            filename,
            "unknown filename extension.".to_string(),
        )),
    }
}

pub fn load_files(options: &Options) -> Vec<LoadedFile> {
    let mut loaded = Vec::new();
    let input = options.inputs.first().cloned().unwrap_or_default();
    let mut filenames = input.split(' ');
    for filename in &mut filenames {
        let one = load_one_file(filename).unwrap();
        loaded.push(one);
    }
    loaded
}
