//! Minimal terminal handling for the interactive renderer, using
//! direct libc calls (via `extern "C"`) for terminal size, raw mode
//! and non-blocking input.  No external crates are needed.

use std::io::Write;
use std::os::unix::io::RawFd;

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

impl Default for Termios {
    fn default() -> Self {
        Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        }
    }
}

const TIOCGWINSZ: u64 = 0x5413;
const TCSANOW: i32 = 0;

extern "C" {
    fn ioctl(fd: RawFd, request: u64, ...) -> i32;
    fn tcgetattr(fd: RawFd, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: RawFd, action: i32, termios: *const Termios) -> i32;
    fn read(fd: RawFd, buffer: *mut u8, count: usize) -> isize;
}

pub fn terminal_size() -> Result<(usize, usize), std::io::Error> {
    let mut size = Winsize::default();
    let result = unsafe { ioctl(0, TIOCGWINSZ, &mut size as *mut Winsize) };
    if result != 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok((size.ws_col as usize, size.ws_row as usize))
}

pub struct RawMode {
    original: Option<Termios>,
}

impl RawMode {
    pub fn enable() -> RawMode {
        unsafe {
            let mut original = Termios::default();
            if tcgetattr(0, &mut original) != 0 {
                return RawMode { original: None };
            }
            let mut raw = original;
            // cfmakeraw(3) equivalent values for Linux.
            raw.c_iflag &= !(0x0001 | 0x0002 | 0x0010 | 0x0020 | 0x0040);
            raw.c_oflag &= !(0x0001);
            raw.c_lflag &= !(0x0008 | 0x0002 | 0x8000 | 0x0001);
            raw.c_cflag &= !(0x0100 | 0x0030);
            raw.c_cflag |= 0x0030;
            raw.c_cc[6] = 0; // VMIN
            raw.c_cc[5] = 0; // VTIME
            tcsetattr(0, TCSANOW, &raw);
            RawMode {
                original: Some(original),
            }
        }
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        if let Some(original) = self.original {
            unsafe {
                tcsetattr(0, TCSANOW, &original);
            }
        }
    }
}

/// Reads any pending bytes from stdin without blocking.  Returns true
/// if a quit key (`q` or Ctrl-C) is among them.
pub fn quit_requested() -> bool {
    let mut buffer = [0u8; 64];
    let count = unsafe { read(0, buffer.as_mut_ptr(), buffer.len()) };
    if count <= 0 {
        return false;
    }
    buffer[..count as usize]
        .iter()
        .any(|byte| *byte == b'q' || *byte == 3)
}

pub fn write_hide_cursor(out: &mut impl Write) {
    let _ = out.write_all(b"\x1b[?25l");
}

pub fn write_show_cursor(out: &mut impl Write) {
    let _ = out.write_all(b"\x1b[?25h");
}
