mod geometry;
mod inputs;
mod output;
mod rasterizer;
mod terminal;

use geometry::build_triangles;
use inputs::MainError;
use rasterizer::{Rasterizer, Rotation};
use std::error::Error;
use std::io::Write;
use std::time::Instant;

fn main() -> Result<(), Box<dyn Error>> {
    let options = inputs::parse_cli();
    let loaded = inputs::load_files(&options);
    let triangles = build_triangles(loaded);
    let main_rotation = inputs::rotation_from(&options.x, &options.y, &options.z)?;

    if let Some(image) = &options.image {
        let width = inputs::parse_usize(image.width.as_deref().unwrap_or("0"))?;
        let height = match &image.height {
            Some(value) => inputs::parse_usize(value)?,
            None => width,
        };
        let rotation = inputs::rotation_from(&image.x, &image.y, &image.z)?;
        let colour = !options.no_colour;
        if let Some(webify_value) = &image.webify {
            let frame_count = inputs::parse_usize(webify_value)?;
            return webify(&triangles, rotation, width, height, colour, frame_count);
        }
        let mut rasterizer = Rasterizer::new(width, height);
        rasterizer.render(&triangles, rotation);
        rasterizer.add_newlines();
        if colour {
            print!("{}", output::frame_string(&rasterizer, true));
        } else {
            println!("{}", output::frame_string(&rasterizer, false));
        }
        return Ok(());
    }

    interactive(&triangles, main_rotation, !options.no_colour)
}

fn webify(
    triangles: &Vec<geometry::Triangle>,
    rotation: Rotation,
    width: usize,
    height: usize,
    colour: bool,
    frame_count: usize,
) -> Result<(), Box<dyn Error>> {
    let mut output_text = String::new();
    output_text.push_str("let frames = [\n");
    let frames = if frame_count == 0 { 1 } else { frame_count };
    let step = 2.0 * std::f32::consts::PI / frame_count as f32;
    let mut current = rotation;
    for index in 0..frames {
        let mut rasterizer = Rasterizer::new(width, height);
        rasterizer.render(triangles, current);
        rasterizer.add_newlines();
        output_text.push_str("`\n");
        output_text.push_str(&output::web_frame_string(&rasterizer, colour));
        if index + 1 < frames {
            output_text.push_str("`,\n");
        } else {
            output_text.push_str("`];\n");
        }
        current.y += step;
    }
    print!("{}", output_text);
    Ok(())
}

fn interactive(
    triangles: &Vec<geometry::Triangle>,
    rotation: Rotation,
    colour: bool,
) -> Result<(), Box<dyn Error>> {
    let (width, height) = match terminal::terminal_size() {
        Ok(size) => size,
        Err(error) => return Err(Box::new(MainError::IoError(error))),
    };
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    terminal::write_hide_cursor(&mut out);
    let _ = out.flush();
    let _raw = terminal::RawMode::enable();
    let start = Instant::now();
    let mut rasterizer = Rasterizer::new(width, height);
    loop {
        let mut current = rotation;
        current.y = rotation.y + start.elapsed().as_secs_f32();
        rasterizer.render(triangles, current);
        let _ = out.write_all(b"\x1b[1;1H");
        let frame = output::terminal_frame_string(&rasterizer, colour);
        let _ = out.write_all(frame.as_bytes());
        if !colour {
            let _ = out.write_all(b"\n");
        }
        let _ = out.flush();
        if terminal::quit_requested() {
            break;
        }
    }
    terminal::write_show_cursor(&mut out);
    let _ = out.flush();
    Ok(())
}
