{"command":"cat >> src/cli.rs <<'RS'

fn jaro(first: &str, second: &str) -> f64 {
    let a: Vec<char> = first.chars().collect();
    let b: Vec<char> = second.chars().collect();
    if a.is_empty() || b.is_empty() {
        return if a.is_empty() && b.is_empty() { 1.0 } else { 0.0 };
    }
    let max_dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(max_dist);
        let end = (i + max_dist + 1).min(b.len());
        for j in start..end {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[j] {
                j += 1;
            }
            if a[i] != b[j] {
                transpositions += 1;
            }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

fn jaro_winkler(first: &str, second: &str) -> f64 {
    let similarity = jaro(first, second);
    if similarity > 0.7 {
        let prefix = first
            .chars()
            .zip(second.chars())
            .take_while(|(a, b)| a == b)
            .take(4)
            .count();
        similarity + prefix as f64 * 0.1 * (1.0 - similarity)
    } else {
        similarity
    }
}

fn did_you_mean(value: &str, candidates: &[&str]) -> Option<String> {
    let mut best: Option<(f64, String)> = None;
    for candidate in candidates {
        let confidence = jaro_winkler(value, candidate);
        if confidence > 0.8 && (best.is_none() || confidence > best.as_ref().unwrap().0) {
            best = Some((confidence, candidate.to_string()));
        }
    }
    best.map(|(_, candidate)| candidate)
}

fn suggestion_error(
    bin: &str,
    token: &str,
    candidate: &str,
    usage: &str,
) -> ! {
    eprint!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        token, candidate, usage
    );
    std::process::exit(1);
}
