fn long_unknown_top(bin: &str, name: &str, seen: &Seen) -> ! {
    if let Some(candidate) = did_you_mean(name, &["help", "version", "yaw", "pitch", "roll"]) {
        let mut displays = used_displays(MAIN_ORDER, &seen.used());
        let display = match candidate.as_str() {
            "help" => "--help",
            "version" => "--version",
            "yaw" => "--yaw <x>",
            "pitch" => "--pitch <y>",
            _ => "--roll <z>",
        };
        if !displays.contains(&display) {
            displays.push(display);
        }
        let usage = smart_main_usage(bin, &displays);
        suggestion_error(bin, &format!("--{}", name), &candidate, &usage);
    }
    unknown_top(bin, &format!("--{}", name), seen)
}

fn long_unknown_image(bin: &str, name: &str, seen: &Seen, without_input: bool) -> ! {
    if let Some(candidate) = did_you_mean(name, &["help", "version", "webify", "yaw", "pitch", "roll"]) {
        let mut used = seen.used();
        let id = match candidate.as_str() {
            "webify" => "j",
            "yaw" => "x",
            "pitch" => "y",
            "roll" => "z",
            _ => "",
        };
        if !id.is_empty() && !used.iter().any(|item| item == id) {
            used.push(id.to_string());
        }
        let mut displays = used_displays(IMAGE_ORDER, &used);
        // Include the required width if it was not used.
        if seen.count("w") == 0 && !displays.contains(&"-w <width>") {
            // Keep declaration order: width is already in IMAGE_ORDER
            // when `w` is in used; if not, insert it manually below.
        }
        if seen.count("w") == 0 {
            // Insert width in a position consistent with the other
            // displays: before any rotation options, otherwise append.
            let width_display = "-w <width>";
            if !displays.contains(&width_display) {
                displays.push(width_display);
            }
        }
        match candidate.as_str() {
            "help" => displays.push("--help"),
            "version" => displays.push("--version"),
            _ => {}
        }
        let usage = smart_image_usage(bin, without_input, &displays);
        suggestion_error(bin, &format!("--{}", name), &candidate, &usage);
    }
    unknown_image(bin, &format!("--{}", name), seen, without_input)
}
